fortgesetzte_guetergemeinschaft_abfindungsbilanz <- function(bereinigte_restmasse_ohne_abfindungen=NULL,qualifizierte_abfindungen=NULL,bilanznachweis=NULL) {
  masse <- .geld(bereinigte_restmasse_ohne_abfindungen);abfindung <- .geld(qualifizierte_abfindungen)
  .text(bilanznachweis,"bilanznachweis")
  rechenmasse <- .addieren(masse,abfindung);haelfte <- .dividieren(rechenmasse,.bruch(2));saldo <- .subtrahieren(haelfte,abfindung)
  eingaben <- list(bereinigte_restmasse_ohne_abfindungen=bereinigte_restmasse_ohne_abfindungen,qualifizierte_abfindungen=qualifizierte_abfindungen,bilanznachweis=bilanznachweis)
  wert <- list(rechenmasse_mit_abfindung=.bruchteile(rechenmasse),rechnerischer_ehegattenhalbteil=.bruchteile(haelfte),abkoemmlingshalbteil_vor_anrechnung=.bruchteile(haelfte),abkoemmlingssaldo_nach_anrechnung=.bruchteile(saldo))
  ergebnis <- .ergebnis(wert,"EUR","BGB_FORTGESETZTE_GUETERGEMEINSCHAFT_ABFINDUNGSBILANZ",eingaben,list(list(operation="Gew\u00e4hrte qualifizierte Abfindungen zur bereinigten Restmasse addieren, halbieren und vollst\u00e4ndig auf die Abk\u00f6mmlingsh\u00e4lfte anrechnen; rechnerischen Saldo gesondert ausweisen.")),eingaben)
  ergebnis$hinweise <- list("\u00a71501I-Bilanz ohne abweichende Vereinbarung nachAbsatz2; entsprechend\u00a71511III f\u00fcr tats\u00e4chlich aus Gesamtgut gezahlte Ausschlussbetr\u00e4ge. Ein blo\u00df berechneter, noch nicht gezahlter Anspruch ist keine gew\u00e4hrte Abfindung und darf nicht als bereits abgeflossen hinzugerechnet werden. Nur tats\u00e4chlich aus Gesamtgut gew\u00e4hrte, rechtlich einrechenbare Abfindungen f\u00fcr Anteilsverzicht oder entsprechende gezahlte Ausschlussbetr\u00e4ge1511III; qualifizierte Summe und ma\u00dfgebliche Werte vorgeben. Restmasse enth\u00e4lt diese bereits abgeflossenen Betr\u00e4ge gerade nicht und ist nach vorrangigen Verbindlichkeiten/R\u00fcckbehalten bereinigt. Andere Ersatzforderungen/Lasten nach\u00a7\u00a71498bis1500 sowie Vorempf\u00e4nge nach\u00a71503II sind getrennt abzugrenzen; dies ist keine vollst\u00e4ndige Schlussauseinandersetzung. \u00a71503III belastet im Innenverh\u00e4ltnis nur beg\u00fcnstigte Abk\u00f6mmlinge, keine automatische Gleichverteilung der Abfindung. Negativer Abk\u00f6mmlingssaldo bleibt ausdr\u00fccklich blo\u00dfe Rechengr\u00f6\u00dfe und begr\u00fcndet keinen ausgegebenen Nachschuss-/R\u00fcckzahlungsanspruch;\u00a71498 beschr\u00e4nkt die \u00fcberschie\u00dfende\u00a71476II2-Ersatzpflicht auf den \u00fcberlebenden Ehegatten. Rechnerischer Ehegattenhalbteil ist kein Nachweis sofort verf\u00fcgbarer Barauszahlung.")
  ergebnis
}
